source = '''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            top, bottom = min(x[0] for x in cells), max(x[0] for x in cells)
            left, right = min(x[1] for x in cells), max(x[1] for x in cells)
            # Fill the hollow interior and the single gap in the top wall.
            top_ones = [cc for cc in range(left, right + 1) if grid[top][cc] == 5]
            gaps = [cc for cc in range(left, right + 1) if grid[top][cc] == 0]
            if len(gaps) == 1 and top < bottom and left < right:
                gap = gaps[0]
                out[top][gap] = 2
                for rr in range(top + 1, bottom):
                    for cc in range(left + 1, right):
                        if grid[rr][cc] == 0:
                            out[rr][cc] = 2
                if top > 0:
                    left_count = sum(grid[top][cc] == 5 for cc in range(left, gap))
                    right_count = sum(grid[top][cc] == 5 for cc in range(gap + 1, right + 1))
                    if left_count > right_count:
                        for cc in range(0, gap + 1):
                            out[top - 1][cc] = 2
                    else:
                        for cc in range(gap, w):
                            out[top - 1][cc] = 2
    return out
'''
